import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'firebase_options.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await Firebase.initializeApp(options:DefaultFirebaseOptions.currentPlatform);runApp(const App());}
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'Malkify Tasks',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:Colors.indigo),useMaterial3:true),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{final email=TextEditingController(),password=TextEditingController(),task=TextEditingController();bool signup=false;User? get user=>FirebaseAuth.instance.currentUser;
Future<void> auth()async{try{if(signup){await FirebaseAuth.instance.createUserWithEmailAndPassword(email:email.text.trim(),password:password.text);}else{await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.text.trim(),password:password.text);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}setState((){});}
Future<void> add()async{final t=task.text.trim();if(t.isEmpty||user==null)return;await FirebaseFirestore.instance.collection('users').doc(user!.uid).collection('tasks').add({'title':t,'done':false,'createdAt':FieldValue.serverTimestamp()});task.clear();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Malkify Tasks'),actions:[if(user!=null)IconButton(onPressed:()async{await FirebaseAuth.instance.signOut();setState((){});},icon:const Icon(Icons.logout))]),body:user==null?Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),FilledButton(onPressed:auth,child:Text(signup?'Create account':'Sign in')),TextButton(onPressed:()=>setState(()=>signup=!signup),child:Text(signup?'Already registered? Sign in':'New here? Create account'))])):Column(children:[Padding(padding:const EdgeInsets.all(16),child:Row(children:[Expanded(child:TextField(controller:task,decoration:const InputDecoration(hintText:'Add a task'))),IconButton(onPressed:add,icon:const Icon(Icons.add_circle))])),Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').doc(user!.uid).collection('tasks').orderBy('createdAt',descending:true).snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text(s.error.toString()));if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final data=d.data();return CheckboxListTile(value:data['done']==true,title:Text(data['title']??''),onChanged:(v)=>d.reference.update({'done':v??false}),secondary:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>d.reference.delete()));}).toList());}))]));}
